INSERT INTO "MercenarySkills" ("_row", "GrantedEffect", "SupportCount", "PossibleSupports", "EncounterGrantedEffect", "Name", "Description", "RequiredLevel", "__col7", "SkillFamily", "HASH16", "HouseIcon") VALUES
(0, 11442, 3, '[]', NULL, 'Do Nothing', 'This really shouldn''t be here...', 1, 100, NULL, 51031, ''),
(1, 938, 2, '[0,1,42,37,38,39,71,72,73,93,94,95,142,154,155,156,168,169,170,171,172,173,239]', 939, 'Spark', 'Launches unpredictable sparks that move randomly until they hit an enemy or expire.', 1, 100, NULL, 5893, ''),
(2, 2429, 0, '[11,232,233,234,49,50,51,58]', NULL, 'Conductivity', 'Curses all targets in an area, lowering their lightning resistance and giving them a chance to be shocked when hit.', 24, 100, NULL, 41484, ''),
(3, 5385, 1, '[6,7,232,233,234,240]', NULL, 'Orb of Storms', 'Creates a stationary electrical orb that strikes enemies in its area of effect with beams of lightning that can then split to hit more enemies. ', 1, 100, 1, 11879, ''),
(4, 3024, 2, '[42,71,72,73,232,233,234,52,53,54,11,12,93,94,95,65,66,67,168,169,170]', 3025, 'Greater Stormcall', 'Sets markers at many locations. After a short duration, lightning strikes the markers, dealing damage around them.', 12, 100, 5, 3148, ''),
(5, 3026, 2, '[42,71,72,73,232,233,234,52,53,54,11,12,93,94,95,65,66,67,168,169,170,241]', 3027, 'Stormcall', 'Sets a marker at a location. After a short duration, lightning strikes the marker, dealing damage around it.', 12, 100, 5, 7549, ''),
(6, 2305, 2, '[42,37,38,39,71,72,73,93,94,95]', NULL, '[DNT] Unused', '[DNT] Unused', 12, 100, NULL, 29533, ''),
(7, 2306, 2, '[6,7,42,37,38,39,71,72,73,93,94,95,242,86,87,88]', 2307, 'Arc', 'An arc of lightning reaches from the caster to a targeted enemy and chains to other enemies, but not immediately back. Each time the arc chains, it will also chain a secondary arc to another enemy that the main arc has not already hit, which cannot chain further.', 12, 100, NULL, 59005, ''),
(8, 1047, 2, '[232,233,234,37,38,39,71,72,73,93,94,95,147,148,149,150,159,243]', 1048, 'Greater Shock Nova', 'Repeatedly casts rings of Lightning, followed by larger Lightning novas. Each effect deals lightning damage to enemies caught in the area. Damage from this skill is highly likely to shock.', 28, 100, 1, 50290, ''),
(9, 1249, 0, '[232,233,234,37,38,39,52,53,54]', NULL, 'Lightning Warp', 'Waits for a duration before teleporting to a targeted destination, with the duration based on distance and movement speed. When the teleport occurs, lightning damage is dealt both around the area of arrival and departure.', 10, 100, 0, 28757, ''),
(10, 5351, 0, '[11,232,233,234,52,53,54]', NULL, 'Frost Bomb', 'Creates a crystal that pulses with cold for a duration. Each pulse applies a debuff to nearby enemies for a secondary duration which reduces life regeneration rate, and also inflicts Cold Exposure. When the crystal''s duration ends, it explodes, dealing heavy cold damage to enemies around it.', 4, 100, NULL, 10557, ''),
(11, 5787, 2, '[0,1,37,38,39,68,69,70,99,100,101,142,154,155,156]', 5788, 'Frostbolt', 'Fires a slow-moving projectile that pierces through enemies, dealing cold damage.', 1, 100, NULL, 33663, ''),
(12, 5816, 2, '[37,38,39,232,233,234,49,50,51,80,81,82,55,56,57,59,60,61]', 5817, 'Vortex', 'An icy blast explodes around the caster, dealing cold damage to enemies, and leaving behind a whirling vortex which deals cold damage over time and chills enemies caught in it.', 28, 100, 1, 31928, ''),
(13, 64, 2, '[37,38,39,99,100,101,80,81,82,68,69,70,102,148,149,150,168,169,170,83,84,85,244]', 65, 'Ice Nova', 'A circle of ice expands from the caster.', 12, 100, NULL, 61497, ''),
(14, 66, 2, '[37,38,39,99,100,101,80,81,82,68,69,70,102,148,149,150,168,169,170]', 67, 'Ice Nova of Projection', 'A circle of ice expands from the target.', 12, 100, NULL, 61471, ''),
(15, 11463, 1, '[37,38,39,232,233,234,49,50,51,168,169,170]', 11464, 'Flame Wall', 'Creates a wall of fire for a duration, which deals burning damage to everything in its area. Each enemy that enters the wall also receives a secondary burning debuff which persists for a short duration after leaving the wall. Non-enemy projectiles fired through the wall deal added fire damage and apply the wall''s secondary debuff on hit.', 4, 100, 1, 57450, ''),
(16, 1017, 0, '[11,232,233,234,49,50,51,159]', NULL, 'Frost Wall', 'Creates a wall of ice which holds back enemies. Targets under the wall are damaged and pushed back.', 4, 100, 1, 50009, ''),
(17, 5037, 2, '[11,12,232,233,234,49,51,50,68,69,70,148,149,150,80,81,82,59,60,61,83,84,85]', NULL, 'Icestorm', 'Icy bolts rain down over the targeted area. They explode when landing, dealing damage to nearby enemies and chilling them, as well as causing patches of chilled ground.', 28, 100, 1, 28637, 'Art/2DArt/SkillIcons/HouseBardiyaSkill.dds'),
(18, 2405, 0, '[11,232,233,234,49,50,51,58]', NULL, 'Flammability', 'Curses all targets in an area, lowering their fire resistance and giving them a chance to be ignited when hit.', 24, 100, NULL, 40521, ''),
(19, 2420, 0, '[11,232,233,234,49,50,51,58]', NULL, 'Frostbite', 'Curses all targets in an area, lowering their cold resistance and giving them a chance to be frozen when hit.', 24, 100, NULL, 6479, ''),
(20, 12083, 2, '[0,1,37,38,39,99,100,101,148,149,150,102,154,155,156,83,84,85]', NULL, 'Eye of Winter', 'Fires a single eye projectile which constantly releases shard projectiles in a spiral. The shards will damage enemies they impact, dealing cold damage. The eye cannot damage enemies. When the eye dissipates or collides with terrain, it releases a faster spiral of extra shards.', 28, 100, NULL, 57063, ''),
(21, 10655, 0, '[65,66,67,232,233,234,99,100,101]', NULL, 'Frostblink', 'Teleport to a location, damaging enemies and leaving Chilled ground in an area at both ends of the teleport.', 4, 100, 0, 40470, ''),
(22, 4970, 0, '[65,66,67,37,38,39,49,50,51]', NULL, 'Flame Dash', 'Teleport to a location, damaging enemies and leaving a trail of burning ground.', 10, 100, 0, 56180, ''),
(23, 4969, 2, '[65,66,67,37,38,39,49,50,51,55,56,57,159,168,169,170,199]', NULL, 'Greater Flame Dash', 'Repeatedly teleport to many locations, damaging enemies and leaving trails of dangerous burning ground.', 28, 100, 1, 24099, ''),
(24, 3104, 2, '[232,233,234,77,78,79,37,38,39,103,104,105,96,97,98,139,140,141,162,199]', 3105, 'Flameblast', 'Channels to build up a large fiery explosion. The longer it is channelled, the larger the area of effect and damage of the explosion.', 28, 100, NULL, 6446, ''),
(25, 3224, 2, '[37,38,39,232,233,234,77,78,79,55,56,57]', NULL, 'Flame Surge', 'Strikes enemies with a surge of flame. Burning enemies are dealt more damage. Hitting an ignited enemy will create burning ground under them. Damage modifiers don''t apply to this burning ground.', 12, 100, 1, 8801, ''),
(26, 8951, 3, '[]', 8950, 'Flame Aegis', 'Surrounds the caster with a fiery barrier which will absorb incoming fire damage up to a point, then break. This barrier will recharge over time.', 1, 100, NULL, 50414, 'Art/2DArt/SkillIcons/HouseBardiyaSkill.dds'),
(27, 3109, 2, '[232,233,234,77,78,79,37,38,39,162,103,104,105,96,97,98,159,199]', NULL, 'Vaal Flameblast', 'Targets an area and builds up stages in that area based on cast speed. It explodes every 3 stages, until it reaches a maximum of 15. As it gains more stages, the area gets smaller but the damage gets higher.', 28, 100, 1, 29426, ''),
(28, 3, 2, '[232,233,234,0,1,96,97,98,77,78,79,103,104,105,142,154,155,156,168,169,170,22,199]', 4, 'Fireball', 'Unleashes a ball of fire towards a target which explodes, damaging nearby foes.', 1, 100, 4, 324, ''),
(29, 5, 2, '[232,233,234,0,1,96,97,98,77,78,79,103,104,105,168,169,170,199,247]', 6, 'Fireball of Impact', 'Unleashes a ball of fire towards a targeted location which then explodes, damaging nearby foes.', 1, 100, 4, 37821, ''),
(30, 5100, 2, '[232,233,234,0,1,142,37,38,39,6,7,96,97,98,148,149,150,154,155,156,151,152,153,134,77,78,79,168,169,170,199]', 5101, 'Rolling Magma', 'Lob a fiery orb that deals area damage as it hits the ground. The skill chains, bouncing forward to deal damage multiple times.', 1, 100, NULL, 30130, ''),
(31, 2004, 3, '[]', NULL, 'Anger', 'Casts an aura that grants added fire damage to attacks and spells.', 24, 100, NULL, 13235, ''),
(32, 3009, 3, '[]', NULL, 'Purity of Fire', 'Casts an aura that grants fire resistance.', 24, 100, NULL, 33728, ''),
(33, 3014, 3, '[]', NULL, 'Purity of Ice', 'Casts an aura that grants cold resistance.', 24, 100, NULL, 13693, ''),
(34, 3019, 3, '[]', NULL, 'Purity of Lightning', 'Casts an aura that grants lightning resistance.', 24, 100, NULL, 63233, ''),
(35, 11460, 0, '[232,233,234,49,50,51]', 11461, 'Sigil of Power', 'Places a Sigil on the ground, which grants a buff to allies in the area around it for a duration. The Sigil gains stages mana is spent in its area, making the buff more powerful.', 34, 100, NULL, 33661, ''),
(36, 2456, 2, '[232,233,234,42,71,72,73,93,94,95,159,86,87,88]', 2457, 'Ball Lightning of Static', 'Creates a ball of lightning at a location that damages each enemy in an area around it repeatedly with bolts of lightning.', 28, 100, NULL, 30663, ''),
(37, 1978, 3, '[]', NULL, 'Discipline', 'Casts an aura that grants additional energy shield and increased energy shield recharge rate.', 24, 100, NULL, 21708, ''),
(38, 2023, 3, '[]', 2024, 'Wrath', 'Casts an aura that adds lightning damage to attacks, and makes spells deal more lightning damage.', 24, 100, NULL, 38326, ''),
(39, 1141, 0, '[58,37,38,39]', NULL, 'Temporal Chains', 'Curses all enemies in an area, lowering their action speed and making other effects on them expire more slowly.', 24, 100, NULL, 7383, ''),
(40, 10471, 0, '[232,233,234,55,56,57]', 10472, 'Bane', 'Applies a debuff to enemies in an area, which deals chaos damage over time. Casting this spell also triggers any Hexes this Mercenary has.', 24, 100, NULL, 63468, ''),
(41, 2843, 0, '[232,233,234,49,50,51,37,38,39,65,66,67]', NULL, 'Proximity Shield', 'Creates a barrier for a short duration which will negate incoming damage that originates from outside the barrier.', 10, 100, NULL, 16018, 'Art/2DArt/SkillIcons/HouseBardiyaSkill.dds'),
(42, 10803, 0, '[232,233,234,65,66,67,161,159]', NULL, 'Withering Step', 'Grants Elusive and a buff that grants Phasing. While this buff is active, enemies in the surrounding area will be Withered.', 10, 100, 3, 10320, ''),
(43, 2052, 3, '[]', NULL, 'Clarity', 'Casts an aura that grants mana regeneration.', 10, 100, NULL, 28785, ''),
(44, 5504, 0, '[232,233,234,49,50,51,129,130,131,37,38,39]', NULL, 'Wither Totem', 'Creates a Spell Totem that casts a debilitating debuff on enemies in an area, hindering their movement and also inflicts the Withered debuff, which increases the Chaos Damage they take and can stack up to 15 times.', 10, 100, 3, 1911, ''),
(45, 10498, 3, '[]', NULL, 'Malevolence', 'Casts an aura that multiplies damage over time and increases skill effect duration.', 24, 100, NULL, 1516, ''),
(46, 10413, 2, '[49,50,51,55,56,57,142,0,1,133,126,127,128,65,66,67,26,27,28]', 10414, 'Greater Soulrend', 'Fires a nova of slow moving projectiles that turn towards enemies in front of them, damaging and piercing through those they hit, and leeching some of that damage as energy shield. As the projectiles travel, they repeatedly applies a short but powerful chaos damage over time debuff to each enemy in an area around them.', 28, 100, 1, 11671, ''),
(47, 5542, 2, '[126,127,128,49,50,51,0,1,65,66,67,159,55,56,57]', NULL, 'Altar of Chaos', 'Creates a profane altar which continually deals chaos damage over time to enemies around it.', 28, 100, 1, 50670, 'Art/2DArt/SkillIcons/HouseBardiyaSkill.dds'),
(48, 5513, 2, '[49,50,51,55,56,57,142,0,1,126,127,128,6,7,160]', 5514, 'Essence Drain of Wickedness', 'Fires a piercing projectile that applies a damage over time debuff when it hits. Healing the caster for a portion of the debuff damage.', 12, 100, NULL, 39669, ''),
(49, 4343, 1, '[49,50,51,232,233,234,55,56,57,126,127,128,65,66,67]', NULL, 'Scourstorm', 'Surrounds the caster with whipping winds of profane energy that deals chaos damage over time to nearby enemies.', 12, 100, 1, 13441, 'Art/2DArt/SkillIcons/HouseBardiyaSkill.dds'),
(50, 5852, 2, '[49,50,51,37,38,39,55,56,57,232,233,234,132,126,127,128,139,140,141]', 5853, 'Blight', 'Apply a debuff to enemies which deals chaos damage over time. Enemies who aren''t already debuffed by Blight are also hindered for a shorter secondary duration, slowing their movement. Continued channelling adds layers of damage to the debuff, each with their own duration.', 1, 100, NULL, 8450, ''),
(51, 8868, 0, '[37,38,39,232,233,234,77,78,79,163,96,97,98]', NULL, 'Bodyswap', 'Explodes your body and recreates it at the location of a targeted enemy or corpse, dealing spell damage in an area at both locations. If targeting a corpse, the corpse will also explode, dealing damage around it.', 10, 100, NULL, 4927, ''),
(52, 10684, 3, '[]', NULL, 'Pride', 'Casts an aura that causes nearby enemies to take more physical damage.', 24, 100, NULL, 18793, ''),
(53, 1976, 0, '[49,50,51,65,66,67,159,232,233,234]', NULL, 'Vaal Vitality', 'Casts a temporary aura that grants life regeneration.', 28, 100, NULL, 14889, 'Art/2DArt/SkillIcons/HouseCyaxanSkill.dds'),
(54, 11845, 2, '[49,50,51,37,38,39,11,12,232,233,234,126,127,128,55,56,57,126,127,128,217,218,219,157,158,164,165,166,123,124,125]', 11846, 'Reap', 'Creates a bloody scythe that swipes an area applying a physical damage over time debuff and hitting enemies with physical damage.', 28, 100, NULL, 14064, ''),
(55, 5323, 2, '[49,50,51,232,233,234,157,158,217,218,219,164,165,166,37,38,39,123,124,125]', 5324, 'Corrupted Blade Vortex of the Scythe', 'This spell creates a swarm of ethereal blades which briefly orbit in an area around you, dealing damage and applying corrupted blood to all enemies in their radius.', 12, 100, NULL, 8958, ''),
(56, 12337, 2, '[49,50,51,65,66,67,126,127,128,232,233,234,159,55,56,57,217,218,219,164,165,166,248]', 12338, 'Vaal Reap', 'Creates a bloody scythes that swipes an area, hitting enemies with physical damage. An area of boiling blood is left beneath them for a duration which deals physical damage over time.', 28, 100, 1, 1185, ''),
(57, 11811, 2, '[49,50,51,126,127,128,37,38,39,55,56,57,164,165,166]', 11812, 'Exsanguinate', 'Releases several tendrils of blood. The tendrils deal physical damage and inflict a physical damage over time debuff to enemies, which can stack up to 3 times. Effects which allow skills to chain can apply to these tendrils.', 12, 100, NULL, 40439, ''),
(58, 5760, 1, '[232,233,234,55,56,57,49,50,51,126,127,128,55,56,57,164,165,166]', NULL, 'Boiling Blood', 'Creates a pool of boiling blood on using a travel skill, which deals physical damage over time to enemies within it.', 12, 100, NULL, 44422, 'Art/2DArt/SkillIcons/HouseCyaxanSkill.dds'),
(59, 3064, 2, '[232,233,234,52,53,54,65,66,67,159,11,12,217,218,219,157,158,164,165,166]', NULL, '[DNT] Unused', '[DNT] Unused', 1, 100, NULL, 11256, ''),
(60, 1189, 3, '[]', NULL, 'Blasphemy Enfeeble', 'Casts an aura that curses all enemies in an area, reducing their accuracy and making them deal less damage.', 24, 100, NULL, 26391, ''),
(61, 3255, 0, '[232,233,234,49,50,51,37,38,39,65,66,67,159,126,127,128]', NULL, 'Desecrate', 'Desecrates the ground, spawning corpses based on monsters in the current area and dealing chaos damage over time to enemies.', 16, 100, NULL, 21523, ''),
(62, 3300, 0, '[49,50,51,37,38,39,65,66,67]', NULL, 'Bone Offering', 'Consumes a corpse, granting the owners minions the power to block both attacks and spells. The skill consumes other nearby corpses, increasing the duration for each corpse consumed.', 12, 100, 1, 44467, ''),
(63, 3290, 0, '[49,50,51,37,38,39,65,66,67]', NULL, 'Flesh Offering', 'Consumes a corpse, which temporarily empowers the owners minions with swiftness. The skill consumes other nearby corpses, increasing the duration for each corpse consumed.', 12, 100, 1, 61730, ''),
(64, 11829, 3, '[]', NULL, 'Relic of Binding', 'Summons a stationary Relic which generates an aura. Enemies in the aura will take damage based on their life when using movement skills.', 28, 100, NULL, 62758, 'Art/2DArt/SkillIcons/HouseBardiyaSkill.dds'),
(65, 1289, 2, '[37,38,39,200,217,218,219,164,165,166,177,178,179,188,189,190,245]', NULL, 'Summon Skeletons', 'Summons Skeleton Warrior minions. They use a melee attack and die after a duration.', 10, 100, NULL, 17409, ''),
(66, 3188, 2, '[37,38,39,96,97,98,168,169,170,177,178,179,188,189,190,200,249]', NULL, 'Summon Raging Spirit', 'Summons a short-lived flaming skull that rushes at nearby enemies and attacks them rapidly, converting all its physical damage to fire. ', 4, 100, NULL, 19108, ''),
(67, 671, 2, '[200,217,218,219,164,165,166,177,178,179,188,189,190,191,192,258]', 672, 'Raise Zombie of Gigantism', 'Raises a single gigantic zombie minion from a corpse, which will follow you and attack enemies with a melee strike.', 1, 100, NULL, 52491, ''),
(68, 669, 2, '[200,37,38,39,164,165,166,177,178,179,232,233,234,123,124,125,157,158,196,197,198,26,27,28]', 670, 'Raise Zombie of Falling', 'Raises necromantic energies into the sky where they coalesce into a zombie minion. The minion then attacks by falling to the ground, causing an impact that deals damage in an area and kills the zombie.', 1, 100, NULL, 57377, ''),
(69, 10415, 2, '[0,1,142,6,7,183,184,185,37,38,39,148,149,150,143,144,145,174,175,176,26,27,28,250]', 10416, 'Soulrend of Reaping', 'Fires a projectile that deals chaos damage to enemies it hits and leeches some of that damage as energy shield.', 28, 100, NULL, 10742, ''),
(70, 11977, 2, '[49,50,51,52,53,54,148,149,150,183,184,185,232,233,234,37,38,39,187,143,144,145,174,175,176,26,27,28]', NULL, 'Voltaxic Burst', 'Each cast of this spell waits for a short duration, releasing a burst of lightning and chaos spell damage in the surrounding area when that duration ends. Enemies killed by this damage, or shortly after, will explode.', 12, 100, NULL, 52144, ''),
(71, 11443, 1, '[143,144,145,146,49,50,51,157,158,65,66,67,232,233,234,148,149,150,174,175,176]', NULL, 'Void Sphere', 'Creates a Void Sphere which Hinders enemies in an area around it, with the debuff being stronger on enemies closer to the sphere. It also regularly releases pulses of area damage. The Void Sphere will consume the corpses of any enemies which die in its area.', 34, 100, NULL, 52783, ''),
(72, 5954, 2, '[183,184,185,232,233,234,37,38,39,148,149,150,143,144,145,174,175,176,26,27,28]', NULL, 'Dark Bargain', 'Sacrifices life from a nearby allied Skeleton minion to deal chaos damage in an area around it. This effect will chain to other nearby allied skeletons. If there are no nearby allied Skeletons it will  deal damage around the caster instead.', 28, 100, NULL, 35371, ''),
(73, 3306, 2, '[183,184,185,232,233,234,37,38,39,148,149,150,174,175,176,157,158,143,144,145,186,26,27,28]', NULL, 'Profane Cascade', 'Pillars of unholy stone emerge from the ground in a series of small bursts, each damaging enemies caught in the area.', 28, 100, NULL, 51539, 'Art/2DArt/SkillIcons/HouseBardiyaSkill.dds'),
(74, 11830, 3, '[]', NULL, 'Summon Seeking Void', 'Summons a living void that seeks nearby enemies, continually firing bolts of chaotic energy while doing so.', 28, 100, 1, 54144, 'Art/2DArt/SkillIcons/HouseBardiyaSkill.dds'),
(75, 12003, 2, '[183,184,185,232,233,234,37,38,39,148,149,150,143,144,145,174,175,176,0,1,142,129,130,131,26,27,28]', NULL, 'Forbidden Rite Totem', 'Creates a Spell Totem that casts an exploding projectile towards targets and extra projectiles surrounding it. The projectiles deal chaos damage based on the totem''s life and energy shield. Casting this spell damages the totem.', 16, 100, 1, 29071, ''),
(76, 9320, 0, '[11,232,233,234,49,50,51,58]', NULL, 'Despair', 'Curses all targets in an area, lowering their chaos resistance.', 24, 100, NULL, 56742, ''),
(77, 6392, 3, '[]', NULL, 'Envy', 'Casts an aura that adds chaos damage to attacks and spells.', 24, 100, NULL, 17515, ''),
(78, 10486, 3, '[]', NULL, 'Zealotry', 'Casts an aura that grants bonuses to damage and critical strike chance of spells, and gives a chance to create Consecrated Ground against stronger enemies.', 24, 100, NULL, 14498, ''),
(79, 2802, 0, '[232,233,234,206,207,208,49,50,51,65,66,67,159]', NULL, 'Smoke Mine', 'Throws a mine that will then cause teleportation when detonated. Creates clouds of smoke that blinds enemies, and gives a temporary buff to movement speed. ', 10, 100, NULL, 64528, ''),
(80, 1985, 3, '[]', NULL, 'Grace', 'Casts an aura that grants evasion.', 24, 100, NULL, 2792, ''),
(81, 10824, 3, '[]', NULL, 'Summon Skitterbots', 'Summons a Chilling Skitterbot and a Shocking Skitterbot, which will trigger traps and detonate mines. Mines detonated by Skitterbots will re-arm and can then be detonated again. The Skitterbots grant more trap and mine damage, and cannot be targeted or damaged.', 16, 100, NULL, 44296, ''),
(82, 2761, 0, '[65,66,67,159,49,50,51,213,214,215,209,210,211,71,72,73,0,1,86,87,88]', NULL, 'Vaal Lightning Trap', 'Throws a trap that launches a ring of projectiles through the enemy that set it off, dealing lightning damage to them and subsequent targets and leaving a trail of shocked ground.', 12, 100, 1, 25149, ''),
(83, 8703, 0, '[65,66,67,49,50,51,232,233,234,37,38,39]', NULL, 'Trarthan Agility', 'Creates a temporary aura that grants action speed.', 28, 100, NULL, 38072, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(84, 2859, 2, '[213,214,215,206,207,208,209,210,211,212,154,155,156,151,152,153,0,1,201]', NULL, 'Spectral Throw of Trarthus', 'Throws a trap which, once triggered, fires many spectral weapons. They fly out in all directions and then return to where the trap triggered, in a spinning attack that damages enemies in their path.', 12, 100, NULL, 62393, ''),
(85, 12023, 2, '[213,214,215,206,207,208,209,210,211,212,154,155,156,151,152,153,201]', NULL, 'Spectral Helix of Trarthus', 'Throws a trap which, once triggered, fires a spectral weapon. It spins around while flying in a large spiral, damaging enemies in its path, and bouncing if it collides with walls.', 12, 100, NULL, 28988, ''),
(86, 2100, 0, '[213,214,215,206,207,208,65,66,67,159,217,218,219,49,50,51]', NULL, 'Bear Trap', 'Throws a trap that damages and immobilises an enemy for a duration based on how much damage was dealt. After the immobilise expires, a debuff remains on the enemy for a duration, lowering their movement speed by an amount which lessens over time. The affected enemy will take increased damage from traps and mines until the debuff expires.', 4, 100, NULL, 13711, ''),
(87, 12010, 2, '[232,233,233,206,207,208,212,213,214,215,157,158,148,149,150,174,175,176,209,210,211,201,123,124,125]', NULL, 'Blade Trap', 'Throws a trap which, once triggered, swings two copies the equipped weapon around it in circles, each repeatedly damaging enemies it spins through.', 12, 100, NULL, 11054, ''),
(88, 2458, 2, '[206,207,208,213,214,215,42,71,72,73,209,210,211,232,233,234,202,86,87,88]', NULL, 'Ball Lightning of Orbiting Trap', 'Throws a trap which, once triggered, fires a single projectile which moves in a spiral while damaging each enemy in an area around it repeatedly with bolts of lightning.', 28, 100, NULL, 37561, ''),
(89, 1250, 2, '[206,207,208,213,214,215,42,71,72,73,209,210,211,232,233,234,202,201,86,87,88]', NULL, 'Lightning Warp Trap', 'Throws a trap which, once triggered, teleports to a targeted destination. When the teleport occurs, lightning damage is dealt to the area around both where the trap was and where it teleported to. ', 28, 100, NULL, 5247, ''),
(90, 9461, 2, '[206,207,208,213,214,215,42,71,72,73,209,210,211,232,233,234,65,66,67,159,251,86,87,88]', NULL, 'Lightning Spire Trap', 'Throws a trap which, once triggered, will repeatedly strike multiple areas around it for a duration, dealing lightning damage.', 28, 100, 1, 8075, ''),
(91, 2756, 2, '[206,207,208,213,214,215,0,1,6,7,171,172,173,42,71,72,73,209,210,211,212,201,202,246,86,87,88]', NULL, 'Lightning Trap', 'Throws a trap that launches a ring of projectiles through the enemy that set it off, dealing lightning damage to them and subsequent targets.', 12, 100, NULL, 17037, ''),
(92, 2735, 2, '[71,72,73,232,233,234,37,38,39,93,94,136,137,138,148,149,150]', NULL, 'Unnerving Blast', 'Creates a delayed explosion at a targeted area which unnerves enemies on hit. The explosion does physical damage partially converted to lightning.', 16, 100, 1, 19034, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(93, 9485, 0, '[120,121,122,232,233,234,65,66,67,136,137,138]', NULL, 'Charged Dash of the Arcane', 'Projects an illusion which gains stages while it moves, until it stops at a maximum total distance. Waves of area damage frequently pulse along its path. Increases and reductions to spell damage apply to the damage this attack deals.', 28, 100, 1, 5673, ''),
(94, 12127, 1, '[232,233,234,148,149,150,136,137,138,49,50,51,65,66,67,159]', NULL, 'Tornado of Elemental Turbulence', 'Creates a Tornado of a random element that hinders and repeatedly damages enemies around it, converting physical damage to its element. The Tornado will chase down enemies for a duration.', 34, 100, 1, 23225, ''),
(95, 2335, 3, '[]', NULL, 'Arctic Armour', 'Conjures an icy barrier that chills enemies on hit. The barrier creates chilled ground while moving, and causes less Fire and Physical damage while stationary.', 16, 100, NULL, 55367, ''),
(96, 11453, 0, '[37,38,39,65,66,67,159,232,233,234,49,50,51]', NULL, 'Frost Shield', 'Places a Frost Shield that drains energy shield for one second or until none remains, gaining stages while this drain occurs. The Frost Shield takes and prevents some damage from hits of allies while in its area. Enemies in the area are Chilled.', 34, 100, NULL, 57491, ''),
(97, 5179, 2, '[206,207,208,213,214,215,209,210,211,232,233,234,202,68,69,70,80,81,82,201,123,124,125]', NULL, 'Ice Trap', 'Throws a trap that creates a series of icy runic explosions when triggered, dealing cold damage to all enemies caught in the blasts.', 28, 100, NULL, 62997, ''),
(98, 12340, 0, '[65,66,67,159,49,50,51]', NULL, 'Vaal Arctic Armour', 'Immediately encases the caster in ice, protecting for a duration or until taken damage from a number of hits, and also grants a buff once the cast time has finished. Cannot move or perform non-instant actions while protected in the ice. When the ice breaks, the buff is also removed.', 16, 100, 1, 44455, ''),
(99, 6470, 2, '[206,207,208,213,214,215,209,210,211,232,233,234,202,68,69,70,201]', NULL, '[DNT] UNUSED', '[DNT] UNUSED', 1, 100, NULL, 60048, 'Art/2DArt/SkillIcons/HouseCyaxanSkill.dds'),
(100, 5818, 2, '[206,207,208,213,214,215,209,210,211,232,233,234,202,68,69,70,80,81,82,126,127,128]', 5819, 'Greater Vortex Trap', 'Throw multiple traps that cause icy blasts, dealing cold damage to enemies, and leaving behind whirling vortices which deals cold damage over time and chills enemies caught in them.', 28, 100, 1, 3493, ''),
(101, 2277, 2, '[206,207,208,213,214,215,209,210,211,232,233,234,202,68,69,70,80,81,82,201,0,1]', 2278, 'Creeping Frost Trap', 'Throws a trap which, once triggered, fire an icy projectile that bursts on impact or when reaching the targeted area, dealing area damage and creating a chilling area that deals cold damage over time. This area will creep across the ground towards nearby enemies until its duration expires.', 12, 100, NULL, 9321, ''),
(102, 12478, 2, '[71,72,73,232,233,234,37,38,39,93,94,136,137,138,148,149,150,65,66,67]', NULL, 'Divine Retribution', 'Retaliate against a blocked hit with a surge of divine power, causing multiple waves of lightning bursts to expand outward from a targeted location. ', 16, 100, 1, 24685, ''),
(103, 10492, 2, '[139,140,141,71,72,73,232,233,234,37,38,39,93,94,136,137,138,135,148,149,150]', 10493, 'Divine Ire', 'Channels raw energy to build up stages, damaging surrounding enemies. Releases to unleash this energy in a burst in the surrounding area and a beam forward. Maximum of 10 Stages.', 28, 100, NULL, 45226, ''),
(104, 2080, 1, '[232,233,234,38,37,39,129,130,131,136,137,138,49,50,51,107,148,149,150,114]', NULL, 'Shockwave Totem of Shocking', 'Summons a totem that shakes the earth around it, knocking back and damaging nearby enemies. A portion of physical damage the totem deals is converted to lightning.', 28, 100, 1, 6651, ''),
(105, 10478, 0, '[232,233,234,49,50,51,65,66,67,159,136,137,138,71,72,73,86,87,88]', NULL, 'Wave of Conviction', 'An expanding wave of energy surges forward, damaging enemies in a cone-shaped area over a duration. Each enemy hit is inflicted with Exposure matching the element of which they took the highest damage', 16, 100, NULL, 14732, ''),
(106, 4027, 3, '[]', NULL, 'Herald of Ash', 'Grants a buff providing fire damage based on physical damage. While the buff is active, on enemy kill, other enemies near them will be burned based on the overkill damage. ', 16, 100, NULL, 44334, ''),
(107, 10479, 1, '[232,233,234,49,50,51,65,66,67,159,136,137,138,77,78,79,193,194,195,199]', NULL, 'Wave of Conviction of Trarthus', 'An expanding wave of energy surges outwards, damaging enemies in a ring-shaped area over a duration. The ring then returns, damaging enemies again on the way back.', 16, 100, 1, 4286, ''),
(108, 6662, 2, '[232,233,234,136,137,138,77,78,79,37,38,39,0,1,154,155,156,220,193,194,195,199]', NULL, 'Holy Mortar', 'Fling a blast of holy flame, which explodes on impact dealing a mixture of fire and physical area damage.', 24, 100, NULL, 1577, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(109, 6746, 2, '[232,233,234,49,50,51,136,137,138,77,78,79,37,38,39,65,66,67,159,193,194,195,199]', 6747, 'Meteor', 'Call a meteor from the skies, which crashes down dealing area fire damage to those it hits.', 24, 100, 1, 40723, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(110, 10403, 2, '[232,233,234,49,50,51,216,136,137,138,77,78,79,37,38,39]', 10404, 'Purifying Flame', 'Creates a wave of divine fire dealing damage in a line, then creates Consecrated Ground and deals damage in an area. A larger shockwave then expands outwards, damaging enemies standing on Consecrated Ground that were not already hit.', 1, 100, NULL, 17763, ''),
(111, 6055, 1, '[129,130,131,37,38,39,49,50,51,65,66,67,159,252]', 6056, 'Scorching Ray Totem', 'Creates a Spell Totem that unleashes a beam of fire that burns enemies it touches. Enemies in the beam raises the burning, adding a portion of the beam''s damage in stages. Inflicts Fire Exposure at maximum stages. Enemies who leave the beam continue to burn for a duration.', 12, 100, 1, 47293, ''),
(112, 2348, 1, '[77,78,79,49,50,51,129,130,131,0,1,37,38,39,154,155,156,136,137,138,114,199,253]', NULL, 'Holy Flame Totem', 'Summons a totem that channels to fire a stream of flame at nearby enemies, and creates an area of consecrated ground around the totem.', 4, 100, 1, 47949, ''),
(113, 12243, 2, '[0,1,126,127,128,65,66,67,159,49,50,51,232,233,234,55,56,57]', 12244, 'Vaal Caustic Arrow', 'Fires a slow-moving serpentine arrow which deals chaos damage while piercing enemies, and leaves a trail of caustic ground. Enemies standing on the caustic ground take chaos damage over time.', 28, 100, 1, 36274, ''),
(114, 688, 2, '[0,1,232,233,234,49,50,51,126,127,128,157,158,120,121,122,143,144,145,113,2,171,172,173,22]', 690, 'Caustic Arrow', 'Fires an arrow which deals chaos damage in an area on impact, and spreads caustic ground. Enemies standing on the caustic ground take chaos damage over time.', 1, 100, NULL, 58174, ''),
(115, 6943, 0, '[232,233,234,143,144,145]', NULL, 'Chaotic Burst', 'Deals physical and chaos attack damage in an area.', 16, 100, NULL, 26913, 'Art/2DArt/SkillIcons/HouseBardiyaSkill.dds'),
(116, 8887, 2, '[0,1,157,158,183,184,185,120,121,122,154,155,156,33,34,35]', NULL, 'Chaotic Shot', 'Fire a rapidly decelerating arrow that converts part of the physical damage it deals to chaos. When it comes to a stop, it will trigger Chaotic Burst.', 16, 100, NULL, 18986, 'Art/2DArt/SkillIcons/HouseBardiyaSkill.dds'),
(117, 9781, 2, '[0,1,232,233,234,49,50,51,126,127,128,157,158,120,121,122,143,144,145,113,259]', NULL, 'Toxic Rain', 'Fire arrows into the air that rain down around the targeted area, dealing damage to enemies they hit and creating spore pods where they land. Each spore pod deals chaos damage over time to nearby enemies and slows their movement speed. The pods last for a duration before bursting, dealing area damage.', 12, 100, NULL, 38628, ''),
(118, 9771, 2, '[0,1,49,50,51,126,127,128,157,158,120,121,122,143,144,145,33,34,35,14,74,113]', NULL, 'Scourge Arrow of Menace', 'Fire an arrow that leaves a spore pod in its wake. The spore pod blooms, firing thorn arrows, which travel for a short time before dissipating. Modifiers that cause additional projectiles to be fired will only apply to the initial arrows, each of which leaves its own spore pod.', 28, 100, NULL, 28502, ''),
(119, 9376, 0, '[232,233,234,49,50,51,65,66,67,159,180,181,182,30,31,32]', 9377, 'Intimidating Cry', 'Performs a warcry, taunting nearby enemies to attack the user and exerting subsequent attacks. The user and nearby allies gain a buff that grants movement speed.', 10, 100, NULL, 38311, ''),
(120, 9569, 2, '[232,233,234,223,164,165,166,120,121,122,229,230,231,203,204,205,191,192,46]', NULL, 'Ground Slam', 'Slams the ground, creating a wave that travels forward and damages enemies with an increased chance to stun. The wave deals more damage to closer enemies. ', 1, 100, NULL, 53728, ''),
(121, 110, 0, '[232,233,234,120,121,122,229,230,231,164,165,166,222]', NULL, 'Leap Slam', 'Jump through the air, damaging and knocking back enemies when landing.', 10, 100, NULL, 2135, ''),
(122, 1578, 0, '[49,50,51,65,66,67,159,37,38,39,224]', NULL, 'Molten Shell', 'Applies a buff that adds armour, and can take some of the damage from hits before being depleted.', 16, 100, NULL, 21036, ''),
(123, 1603, 3, '[]', NULL, 'Endure', 'Grants endurance charges to all nearby allies.', 1, 100, NULL, 57171, 'Art/2DArt/SkillIcons/HouseKeitaSkill.dds'),
(124, 6095, 0, '[120,121,122,65,66,67,159,232,233,234,229,230,231,164,165,166,123,124,125]', NULL, 'Burrow', 'Dive underground, dealing attack damage to nearby enemies and burrowing towards a targeted location. Then, erupt from the earth, dealing attack damage in an area.', 28, 100, NULL, 31440, 'Art/2DArt/SkillIcons/HouseKeitaSkill.dds'),
(125, 11275, 2, '[229,230,231,164,165,166,232,233,234,120,121,122,217,218,219,123,124,125,254]', 11276, 'Sunder of Trarthus', 'Slams the ground, creating a slow wave of churning terrain that damages enemies in a sequence of areas. A number of enemies hit by the wave will release a shockwave, damaging other enemies around them. Using the skill again will stop the previous wave. When the wave reaches a target or terrain, it can restart aiming towards an enemy, if one is in range.', 12, 100, NULL, 17654, ''),
(126, 8975, 2, '[229,230,231,164,165,166,232,233,234,120,121,122,217,218,219,65,66,67,159,203,204,205,123,124,125]', NULL, 'Tectonic Cascade', 'Create a cascading series of concussive eruptions which deal attack damage.', 28, 100, 1, 40527, 'Art/2DArt/SkillIcons/HouseKeitaSkill.dds'),
(127, 5463, 2, '[229,230,231,164,165,166,232,233,234,49,50,51,120,121,122,217,218,219,110,111,112,123,124,125]', NULL, 'Earthquake of Amplification', 'Smashes the ground, dealing damage in an area and cracking the earth. The crack will erupt in a powerful aftershock after a long duration. Cracks created before the first one has erupted will not generate their own aftershocks.', 28, 100, NULL, 41346, ''),
(128, 1997, 3, '[]', NULL, 'Determination', 'Casts an aura that grants armour.', 24, 100, NULL, 52845, ''),
(129, 9580, 2, '[229,230,231,164,165,166,221,217,218,219,120,121,122,232,233,234,65,66,67,159,203,204,205,123,124,125]', NULL, 'Vaal Ground Slam', 'Slams the ground, creating a wave that travels in all directions that damages enemies with an increased chance to stun. The wave deals more damage to closer enemies.', 28, 100, 1, 10712, ''),
(130, 4880, 0, '[232,233,234,49,50,51,65,66,67,159,180,181,182,30,31,32]', NULL, 'Infernal Cry', 'Performs a warcry, taunting nearby enemies to attack the user and exerting subsequent attacks. The user and nearby allies gain a buff that grants a portion of their physical damage as extra fire damage. In addition to being taunted, enemies are inflicted with a secondary debuff causing them to explode when they die, dealing fire damage in an area.', 24, 100, NULL, 59259, ''),
(131, 12235, 2, '[77,78,79,232,233,234,229,230,231,96,97,98,225,120,121,122,76,40,193,194,195,199]', 12236, 'Volcanic Fissure of Snaking', 'Slam the ground, creating a winding fissure that deals area damage while travelling outwards. When it reaches the target location it erupts dealing damage in an area. After erupting, the fissure can continue to move towards enemies to cause further eruptions.', 12, 100, NULL, 53235, ''),
(132, 12136, 0, '[49,50,51,37,38,39,65,66,67,47]', NULL, 'Flame Link', 'Targets an ally to apply a buff which links to them for a duration, which grants added fire damage to the linked target. If the target dies while linked, the caster will also die. ', 34, 100, NULL, 47364, ''),
(133, 5924, 1, '[49,50,51,232,233,234,77,78,79,120,121,122,225,193,194,195,199]', NULL, 'Ashen Fissure', 'Creates a fiery fissure which deals attack damage, partially converting physical damage to fire. Enemies struck have a chance to be covered in ash.', 28, 100, NULL, 42361, 'Art/2DArt/SkillIcons/HouseKeitaSkill.dds'),
(134, 9627, 1, '[49,50,51,232,233,234,77,78,79,120,121,122,9,225,123,124,125,193,194,195,199]', NULL, 'Consecrated Path', 'Slams the ground at a targeted location. If an enemy is near the targetted location, teleport to it from a short distance away, slam, and create an area of consecrated ground. ', 28, 100, NULL, 3093, ''),
(135, 8910, 1, '[77,78,79,232,233,234,96,97,98]', NULL, 'Triggerslam', 'On landing from Leap Slam, cause a fiery eruption which deals attack damage, partially converting physical to fire.', 10, 100, NULL, 18149, 'Art/2DArt/SkillIcons/HouseKeitaSkill.dds'),
(136, 8976, 2, '[232,233,234,77,78,79,120,121,122,225,46,229,230,231,40,191,192,193,194,195,199]', NULL, 'Tectonic Slam', 'Slams the ground, unleashing a fiery fissure forward, dealing area damage and randomly releasing a number of smaller fissures branching off from it. Consumes an Endurance Charge every third time the ground is slammed with this skill. ', 28, 100, NULL, 6228, ''),
(137, 4807, 2, '[68,69,70,120,121,122,225,229,230,231,232,233,234,48]', NULL, 'Ice Crash', 'Slams the ground, damaging enemies in an area around the impact in three stages of increasing size. Enemies take slightly less damage on the second and third stage, and can only be hit by one stage.', 28, 100, NULL, 11018, ''),
(138, 995, 2, '[68,69,70,120,121,122,62,63,64,59,60,61,80,81,82,99,100,101]', NULL, 'Glacial Hammer', 'Hits enemies, converting some of your physical damage to cold damage. If a non-unique enemy is frozen and is on less than one third life, they will shatter when hit by Glacial Hammer. If striking three times in a row, the third strike will freeze enemies more easily. Requires a Mace, Sceptre or Staff.', 1, 100, NULL, 53217, ''),
(139, 1005, 2, '[68,69,70,83,84,85,49,50,51,65,66,67,232,233,234,90,91,92,59,60,61,99,100,101]', NULL, 'Vaal Glacial Hammer', 'Hits enemies, converting physical damage to cold damage. Traps enemies in a circle of ice so that they can''t escape. ', 24, 100, 1, 47031, ''),
(140, 5464, 2, '[68,69,70,120,121,122,225,229,230,231,232,233,234,52,53,54,99,100,101,59,60,61,123,124,125]', NULL, 'Earthquake of Winter', 'Smashes the ground, dealing damage in an area and cracking the earth. The crack will erupt in a powerful aftershock after a duration. Physical damage dealt is partially converted to cold.', 28, 100, 1, 14816, ''),
(141, 1323, 2, '[120,121,122,164,165,166,62,63,64,191,192,46,21,4,83,84,85]', NULL, 'Heavy Strike of Trarthus', 'Attacks enemies with a forceful blow which has a higher chance to deal double damage the higher your intelligence. Increases and reductions to spell damage apply to attack damage with this skill.', 1, 100, NULL, 38103, ''),
(142, 314, 2, '[120,121,122,164,165,166,110,111,112,191,192,196,197,198,62,63,64,4,46]', NULL, 'Dual Strike', 'Attacks with both weapons, dealing the damage of both in one strike. ', 1, 100, NULL, 10235, ''),
(143, 2013, 3, '[]', NULL, 'Hatred', 'Casts an aura that grants extra cold damage based on physical damage.', 24, 100, NULL, 24482, ''),
(144, 3376, 2, '[77,78,79,171,172,173,65,66,67,159,126,127,128,232,233,234,123,124,125,199]', 3377, 'Vaal Burning Arrow', 'Fires an arrow that explodes, dealing fire damage to its target and other nearby enemies, with an increased chance of igniting them.', 28, 100, 1, 23512, ''),
(145, 5269, 2, '[232,233,234,120,121,122,90,91,92,126,127,128,49,50,51,55,56,57,199,255]', 5270, 'Blast Rain of Trarthus', 'Fires a single arrow up in the air, to rain down at a targeted location. The arrow deals area damage around where it lands, as well as releasing a wave of fire which will apply a burning debuff to enemies.', 28, 100, NULL, 18004, ''),
(146, 2406, 3, '[]', NULL, 'Blasphemy Flammability', 'Casts an aura that curses all enemies in an area, lowering their fire resistance and giving them a chance to be ignited when hit.', 24, 100, NULL, 39298, ''),
(147, 12211, 3, '[]', NULL, 'Alchemist''s Mark', 'Curses an enemy, granting flask charges on hit and creating Burning Ground under the target if a hit Ignites them, and Caustic Ground if it Poisons them.', 24, 100, NULL, 24179, ''),
(148, 2035, 2, '[120,121,122,126,127,128,96,97,98,77,78,79,0,1,142,55,56,57,74,22,199,256]', 2036, 'Burning Arrow', 'Fires a burning arrow that deals fire damage and has a chance to ignite.', 1, 100, NULL, 34665, ''),
(149, 6873, 2, '[120,121,122,126,127,128,49,50,51,65,66,67,159,232,233,234]', 6874, 'Molten Well', 'Fires an incendiary arrow into the air which will create an area of molten ground on impact. Enemies within the molten ground take fire damage over time.', 28, 100, NULL, 59200, 'Art/2DArt/SkillIcons/HouseBardiyaSkill.dds'),
(150, 10882, 1, '[77,78,79,0,1,65,66,67,159,232,233,234,114,129,130,131,260]', NULL, 'Artillery Ballista', 'Summons a ballista totem that propels a sequence of fiery arrows into the air. The arrows impact the ground in a line, each dealing area damage to enemies around it.', 28, 100, 1, 35610, ''),
(151, 1106, 2, '[77,78,79,120,121,122,0,1,126,127,128,96,97,98,75,123,124,125]', NULL, 'Explosive Arrow', 'Fires a sequence of arrows which will stick into an enemy or wall, and then explode, dealing area damage around them, either after a duration or when the maximum number of arrows stuck to that target is reached. ', 28, 100, NULL, 36298, ''),
(152, 2529, 1, '[232,233,234,120,121,122,40,110,111,112,15,139,140,141,196,197,198]', NULL, 'Cyclone of the Empire', 'Moves towards a targeted location while spinning constantly attacking enemies in an area. Enemies struck by this skill are knocked inwards towards the attacker.', 28, 100, NULL, 46739, ''),
(153, 9566, 2, '[120,121,122,110,111,112,62,63,64,46,164,165,166,49,50,51,167,4,196,197,198,65,66,67,159]', NULL, 'Vaal Double Strike', 'Performs two fast strikes with a melee weapon, each of which summons a double for a duration to continuously attack monsters in this fashion.', 28, 100, 1, 37132, ''),
(154, 120, 2, '[120,121,122,191,192,233,232,234,123,124,125,196,197,198,90,91,92]', NULL, 'Holy Sweep', 'Swings a two handed mace or a staff in a circle, calling down holy hammers to land randomly on a number of enemies struck. Hits from these holy hammers cannot be evaded.', 12, 100, NULL, 7395, ''),
(155, 4827, 0, '[30,31,32,180,181,182,65,66,67,159,49,50,51,232,233,234]', NULL, 'Rallying Cry', 'Performs a warcry, taunting nearby enemies to attack the user and exerting subsequent attacks. Nearby allies gain a buff based on the user''s weapon.', 24, 100, NULL, 39265, ''),
(156, 9149, 1, '[232,233,234,164,165,166,123,124,125,110,111,112,23,24,25,196,197,198]', NULL, 'Triggerblades', 'Large blades spike upwards from the ground, dealing attack damage in an area.', 28, 100, NULL, 28026, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(157, 10614, 0, '[65,66,67,159,49,50,51]', NULL, 'Steelskin Ally', 'Applies a buff to an ally which can take some damage from hits before being depleted.', 4, 100, NULL, 17105, 'Art/2DArt/BuffIcons/QuickGuard.dds'),
(158, 784, 2, '[191,192,120,121,122,110,111,112,13,62,63,64,46,164,165,166,4,196,197,198]', NULL, 'Flicker Strike', 'Teleports the character to a nearby enemy and attacks with a melee weapon. Grants a buff that increases movement speed for a duration. The cooldown can be bypassed by expending a Frenzy Charge.', 10, 100, NULL, 61669, ''),
(159, 1597, 3, '[]', NULL, 'Incite', 'Grants frenzy charges to all nearby allies.', 16, 100, NULL, 59409, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(160, 10629, 2, '[23,24,25,164,165,166,120,121,122,232,233,234,126,127,128,17,103,104,105,196,197,198]', NULL, 'Bladestorm', 'Perform a spinning attack, damaging surrounding enemies and creating a bladestorm matching the active stance. The bladestorm repeatedly damages enemies, based on weapon damage and attack time, for a duration. Blood bladestorms are stationary and cause Bleeding, while Sand bladestorms move slowly forwards and Blind enemies. ', 28, 100, NULL, 12357, ''),
(161, 6867, 3, '[]', NULL, 'Bloodthirst', 'Applies a short duration buff to nearby allies, granting them physical damage over time multiplier and attack speed.', 16, 100, NULL, 60880, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(162, 5759, 0, '[232,233,234,49,50,51,65,66,67,159,126,127,128]', NULL, 'Oil Slick', 'Creates an area of oil covered ground, which slows all enemies within it', 1, 100, NULL, 19268, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(163, 5941, 2, '[23,24,25,164,165,166,120,121,122,232,233,234,126,127,128,103,104,105,191,192,196,197,198]', NULL, 'Lacerate', 'Slashes twice, releasing waves of force that damage enemies they hit. Enemies in the middle of the slashes can be hit by both. The slashes will have a chance to inflict bleeding in Blood Stance, or have a wider angle in Sand Stance. ', 12, 100, NULL, 8136, ''),
(164, 10637, 2, '[23,24,25,164,165,166,120,121,122,232,233,234,126,127,128,103,104,105,191,192,18,196,197,198]', NULL, 'Perforate', 'Smash the ground to bring forth multiple spears to damage enemies. When in Blood Stance, multiple spikes burst from the ground in sequence, able to hit enemies multiple times. In Sand Stance, the spikes are thrust outwards. ', 1, 100, NULL, 54006, ''),
(165, 2633, 1, '[0,1,126,127,128,23,24,25,103,104,105,232,233,234,164,165,166]', NULL, 'Blood Mortar', 'Flings a mortar of blood in an arc which deals attack damage on impact and has a high chance to inflict bleeding.', 12, 100, NULL, 26931, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(166, 10999, 2, '[120,121,122,0,1,19,90,91,92,171,172,173,6,7,83,84,85,86,87,88,148,149,150,174,175,176]', NULL, 'Kinetic Bolt', 'Fires a projectile that changes direction in a zig-zag pattern at regular intervals or when hitting enemies. Each time it changes direction, a secondary projectile breaks off, flying in the direction it changed away from.', 1, 100, NULL, 12583, ''),
(167, 4602, 2, '[120,121,122,0,1,19,90,91,92,171,172,173,6,7,83,84,85,86,87,88,148,149,150,174,175,176,22,142]', NULL, 'Kinetic Blast of Clustering', 'Fires a projectile from a Wand that causes a series of area explosions in a secondary radius around its point of impact, each damaging enemies.', 28, 100, NULL, 16356, ''),
(168, 1592, 1, '[120,121,122,148,149,150,174,175,176,0,1,90,91,92,83,84,85,86,87,88]', NULL, 'Power Siphon', 'Fires your wand to fire a single projectile each at a number of nearby enemies, granting a power charge if an enemy is killed by, or soon after, the hit.', 12, 100, NULL, 26705, ''),
(169, 3161, 2, '[120,121,122,0,1,154,155,156,90,91,92,148,149,150,174,175,176,83,84,85,86,87,88]', NULL, 'Barrage', 'Fires individual projectiles repeatedly with a Bow or Wand. These projectiles have a small randomised spread.', 12, 100, NULL, 1356, ''),
(170, 4601, 2, '[65,66,67,159,0,1,154,155,156,90,91,92,148,149,150,174,175,176,22,83,84,85,86,87,88]', NULL, 'Greater Kinetic Blast', 'Fires many projectiles from a Wand that cause series'' of area explosions in a secondary radius around their points of impact, each damaging enemies.', 28, 100, 1, 44258, ''),
(171, 4836, 0, '[180,181,182,232,233,234,49,50,51,65,66,67]', NULL, 'Inspiring Cry', 'Taunts nearby enemies while granting increased damage and mana regeneration rate to nearby allies.', 12, 100, NULL, 65473, ''),
(172, 1165, 0, '[11,12,232,233,234,37,38,39,58]', NULL, 'Elemental Weakness', 'Curses all targets in an area, lowering their elemental resistances.', 24, 100, NULL, 5689, ''),
(173, 10872, 1, '[120,121,122,0,1,49,50,51,108,217,218,219,109]', NULL, 'Ensnaring Arrow', 'Fires an arrow that remains in the ground behind its final target, tethering that enemy to it. Ensnared enemies have less movement speed while trying to break the snare. The snare will break if they leave the area of effect.', 16, 100, 1, 12667, ''),
(174, 4043, 3, '[]', NULL, 'Poacher''s Mark', 'Curses an enemy, lowering their physical damage reduction, and adding physical damage to all hits against them. Attacking the cursed enemy will grant life and mana, and killing them will grant a frenzy charge. ', 16, 100, NULL, 27805, ''),
(175, 9503, 2, '[120,121,122,154,155,156,232,233,234,217,218,219,164,165,166,110,111,112]', NULL, 'Rain of Arrows of Saturation', 'Fires multiple arrows into the air, to slowly land in sequence after a delay, starting at the targeted location and spreading outwards in all directions. Each arrow deals damage in an area around it. Half of the arrows will land directly on targets if there are targets in their range.', 12, 100, 1, 40759, ''),
(176, 5160, 2, '[120,121,122,154,155,234,217,218,219,164,165,166,110,111,112,0,1,114,129,130,131]', NULL, 'Siege Ballista of Trarthus', 'Summons a ring of ballista totems around a targeted location. These ballistae fire once at the targeted location and then expire.', 12, 100, 1, 44144, ''),
(177, 3990, 2, '[120,121,122,154,155,234,217,218,219,164,165,166,110,111,112,0,1,115,113,6,7,74,22]', NULL, 'Tornado Shot', 'Fires a piercing shot that travels until it reaches the targeted location. It will then fire projectiles out in all directions from that point, which will travel for a short time before disappearing.', 28, 100, NULL, 8030, ''),
(178, 10865, 2, '[120,121,122,154,155,234,217,218,219,164,165,166,110,111,112,0,1,114,129,130,131,171,172,173]', NULL, 'Shrapnel Ballista', 'Summons a ballista totem that fires multiple arrows with extreme force, breaking them apart into shrapnel. Enemies can be hit by multiple arrows from the same attack.', 4, 100, 1, 61903, ''),
(179, 12361, 2, '[120,121,122,0,1,217,218,219,142,151,152,153,154,155,156,164,165,166]', NULL, 'Greater Split Arrow', 'Fires multiple arrows which redirect and split midair multiple times.', 28, 100, 1, 8546, ''),
(180, 396, 2, '[120,121,122,0,1,217,218,219,142,151,152,153,154,155,156,164,165,166,6,7,171,172,173,23,24,25]', NULL, 'Split Arrow', 'Fires multiple arrows at different targets.', 1, 100, NULL, 43202, ''),
(181, 1923, 2, '[55,56,57,49,50,51,120,121,122,164,165,166,126,127,128,103,104,105,171,172,173,0,1,6,7,22]', 1924, 'Puncture', 'Fires a puncturing arrow, which causes a bleeding debuff affected by modifiers to skill duration.', 4, 100, NULL, 30431, ''),
(182, 1944, 2, '[42,71,72,73,120,121,122,90,91,92,0,1,142,74,5,22,86,87,88]', NULL, 'Lightning Arrow', 'Fires a charged arrow which damages enemies by causing them to be struck by a bolt of lightning, which also damages a number of surrounding enemies.', 12, 100, NULL, 41051, ''),
(183, 12345, 2, '[42,71,72,73,120,121,122,90,91,92,0,1,6,7,22,257,86,87,88]', NULL, 'Vaal Lightning Arrow', 'Fires charged arrows, which repeatedly travel for a short time before changing direction. When they hit enemies, they are struck by a bolt of lightning which damages a number of surrounding enemies.', 28, 100, 1, 22000, ''),
(184, 12014, 2, '[42,71,72,73,120,121,122,90,91,92,0,1,41,232,233,234,123,124,125,86,87,88]', NULL, 'Storm Rain', 'Fires an arrow into the air to land at a targeted location, dealing area damage. The arrow sticks in the ground where it lands, and periodically fires a beam of lightning to another arrow near it, dealing area damage between them.', 28, 100, NULL, 17216, ''),
(185, 10593, 3, '[]', NULL, 'Precision', 'Casts an aura that grants accuracy and critical strike chance.', 10, 100, NULL, 36279, ''),
(186, 1204, 3, '[]', NULL, 'Assassin''s Mark', 'Curses an enemy, making them more vulnerable to Critical Strikes. Killing the cursed enemy will grant life and mana, and a power charge.', 16, 100, NULL, 47406, ''),
(187, 5294, 2, '[42,71,72,73,120,121,122,90,91,92,0,1,74]', NULL, 'Galvanic Arrow', 'Fire a trio of electrical arrows that quickly dissipate, vanishing shortly after being loosed. The arrows are fired with such force that they create a burst of lightning, damaging enemies in a cone in front of you.', 1, 100, NULL, 27165, ''),
(188, 1943, 2, '[42,71,72,73,120,121,122,90,91,92,0,1,142,74,5,22,86,87,88]', NULL, 'Greater Lightning Arrow', 'Fires multiple charged arrows which damage enemies by causing them to be struck by a bolt of lightning, which also damages a number of surrounding enemies. Lightning damage dealt by this skill has a chance to sap.', 12, 100, 1, 38993, ''),
(189, 188, 2, '[120,121,122,232,233,234,116,117,118,164,165,166,217,218,219,119,191,192,229,230,231]', 190, 'Cleave', 'Swings equipped weapon in an arc, damaging monsters in an area. ', 1, 100, NULL, 8445, ''),
(190, 111, 2, '[120,121,122,232,233,234,116,117,118,164,165,166,217,218,219,229,230,231,222,46,123,124,125]', NULL, 'Leap Slam of Groundbreaking', 'Jump a short distance through the air, damaging and knocking back enemies with your weapon where you land. Enemies you would land on are pushed out of the way.', 10, 100, NULL, 41915, ''),
(191, 5019, 2, '[65,66,67,159,49,50,51,62,63,64,20,120,121,122,4,196,197,198]', NULL, 'Vigilant Strike', 'Attacks enemies with a powerful melee strike which grants Fortification, reducing damage taken from hits. The cooldown can be bypassed by expending an Endurance Charge.', 4, 100, 1, 4988, ''),
(192, 1322, 2, '[120,121,122,164,165,166,62,63,64,191,192,46,21,4,196,197,198,109]', NULL, 'Heavy Strike of Vulnerability', 'Attacks enemies with a forceful blow, with a chance to inflict Vulnerability on hit.', 1, 100, NULL, 64565, ''),
(193, 12035, 2, '[120,121,122,164,165,166,62,63,64,191,192,46,106,49,50,51,229,230,231,4,196,197,198,109]', NULL, 'Boneshatter', 'Attack enemies with a forceful melee strike that also hurts the user. Successive uses will raise the damage dealt both to enemies and the user. Stunning an enemy with the strike releases a damaging pulse.', 28, 100, NULL, 22696, ''),
(194, 2176, 1, '[65,66,67,159,232,233,234,129,130,131]', NULL, 'Decoy Totem', 'Summons a totem that taunts nearby monsters to attack it.', 4, 100, 1, 38104, ''),
(195, 9584, 2, '[65,66,67,159,120,121,122,114,129,130,131,232,233,234,164,165,166,123,124,125]', NULL, 'Vaal Ancestral Warchief', 'Summons an Ancestor Totem which attacks enemies with a powerful cascading slam. If enemies are far away, it will leap toward them as it slams.', 28, 100, 1, 38521, ''),
(196, 1969, 3, '[]', NULL, 'Vitality', 'Casts an aura that grants life regeneration.', 28, 100, NULL, 40419, ''),
(197, 6783, 1, '[65,66,67,159,232,233,234,120,121,122,164,165,166,229,230,231]', NULL, 'Tunnelslam', 'Creates a burrowing charge which travels forwards and then explodes, dealing area damage. Damage from this skill has a chance to intimidate on hit.', 5, 100, 1, 52105, 'Art/2DArt/SkillIcons/HouseKeitaSkill.dds'),
(198, 267, 0, '[30,31,32,180,181,182,232,233,234,49,50,51]', NULL, 'Enduring Cry', 'Performs a warcry, taunting all nearby enemies to attack the user and granting a buff to the user and nearby allies. The user and allied players also gain endurance charges.', 10, 100, 1, 20973, ''),
(199, 8956, 3, '[]', 8957, 'Physical Aegis', 'Surrounds the caster with a physical barrier which will absorb incoming physical damage up to a point, then break. This barrier will recharge over time.', 16, 100, NULL, 17015, 'Art/2DArt/SkillIcons/HouseKeitaSkill.dds'),
(200, 3723, 2, '[0,1,90,91,92,136,137,138,120,121,122,3,151,152,153,154,155,156]', NULL, 'Sanctified Strike', 'Attacks with physical and lightning damage. This attack causes balls of holy energy to launch forth from the enemies hit, divided amongst all enemies hit by the strike. These will deal area attack damage to enemies where they land.', 1, 100, NULL, 53518, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(201, 4033, 1, '[232,233,234,164,165,166,229,230,231,177,178,179,188,189,190,191,192]', NULL, 'Herald of Purity', 'Grants a buff which provides more physical damage. When an enemy is killed while this buff is active, this skill will summon a Sentinel of Purity, or refresh the duration and life of an existing one instead if the maximum number is active. The Sentinels of Purity have a single-target melee attack and an area melee attack.', 16, 100, NULL, 34212, ''),
(202, 5925, 0, '[65,66,67,159,49,50,51]', NULL, 'Enrage', 'Enrage for a short duration, gaining attack speed, movement speed and damage.', 12, 100, NULL, 62530, 'Art/2DArt/SkillIcons/HouseKeitaSkill.dds'),
(203, 12226, 2, '[65,66,67,159,232,233,234,164,165,166,229,230,231,121,120,122,116,117,118]', 12227, 'Vaal Cleave', 'Swings equipped weapon in an arc, damaging monsters in an area. Killing Blows on Rare or Unique enemies grant a buff that improves Cleave for a duration. Killing Blows on Rare Enemies also steal their modifiers for a secondary duration.', 28, 100, 1, 12723, ''),
(204, 5919, 2, '[232,233,234,164,165,166,229,230,231,121,120,122,116,117,118,40,196,197,198,203,204,205]', 5920, 'Slicing Wind', 'Release an arc of pure force, dealing area damage.', 5, 100, NULL, 19808, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(205, 10642, 2, '[232,233,234,116,117,118,120,121,122,164,165,166,229,230,231,123,124,125]', NULL, 'Chain Hook of Trarthus', 'Throws chains ahead, chaining targets hit. Enemies chained will grant rage when hit. When chains are broken, they snap and deal damage in an area around the target they were attached to.', 12, 100, 1, 7182, ''),
(206, 3670, 3, '[]', NULL, 'Raise Spectre: Holy Flame Elementals', 'Raises a spectral version of a Holy Flame Elemental as a minion.', 28, 100, NULL, 47078, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(207, 2680, 2, '[232,233,234,93,94,95,229,230,231,90,91,92,123,124,125]', NULL, 'Touch of God', 'Slams the ground with a fist, with less attack speed, but more damage. This attack deals Lightning Damage to enemies in a large area, with a chance to Shock them. Cannot be Evaded.', 28, 100, 1, 39732, ''),
(208, 9633, 2, '[232,233,234,43,44,45,90,91,92,120,121,122,226]', NULL, 'Smite', 'Performs a melee attack, and causes lightning to strike a nearby enemy, dealing damage in an area. Each target can only be hit once by this skill. Hitting an enemy grants an aura for a duration.', 1, 100, NULL, 55917, ''),
(209, 1339, 2, '[120,121,122,232,233,234,177,178,179,188,189,190,191,192,164,165,166,4,238]', NULL, 'Dominating Blow', 'Attacks enemies with a melee strike, applying a debuff for a short duration. If a non-unique enemy dies while affected by the debuff, the enemy''s corpse will be consumed and a Sentinel of Dominance with the same rarity, prefix and suffix modifiers will be summoned for a longer secondary duration.', 28, 100, NULL, 43742, ''),
(210, 9792, 2, '[65,66,67,232,233,234,164,165,166,136,137,138,177,178,179,16]', NULL, 'Holy Relic', 'Summon a Holy Relic that stays nearby. When an enemy is hit with an attack, the Holy Relic triggers a nova spell with a short cooldown, that deals physical damage to enemies and grants life regeneration to allies in an area around it. This life regeneration is higher when applied to minions.', 4, 100, NULL, 40812, ''),
(211, 4293, 2, '[65,66,67,159,49,50,51,232,233,234,164,165,166,136,137,138]', NULL, 'Beacons of Faith', 'Creates numerous beacons in a large area which explode after a delay, dealing physical area damage. Each explosion creates a patch of consecrated ground.', 24, 100, 1, 50866, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(212, 6273, 2, '[154,155,156,120,121,122,164,165,166,110,111,112,0,1,6,7,171,172,173]', NULL, 'Spectral Shield Throw of Trarthus', 'Throws a spectral shield as a piercing projectile which deals off-hand damage augmented by the defences of the shield. When it reaches the targeted location it will hover in place, repeatedly firing a number of smaller shards as projectiles in all directions. The rate at which it releases shards will increase until all shards have been fired.', 28, 100, NULL, 41834, ''),
(213, 12018, 2, '[232,233,234,120,121,122,164,165,166,229,230,231,46,110,111,112,8,203,204,205]', 12019, 'Shield Crush', 'Swipe your shield, dealing area damage in three waves in front of you. Enemies can be hit by two of the waves where they overlap.', 1, 100, NULL, 21201, ''),
(214, 214, 1, '[232,233,234,120,121,122,164,165,166,229,230,231,228]', 215, 'Shield Charge', 'Charges at a targeted location or enemy, pushing away enemies in the path and repeatedly dealing off-hand damage in a small area forwards. Deals damage in a larger area when reaching the target. The further travelled, the more damage dealt, and the greater the chance of stunning enemies.', 4, 100, NULL, 22850, ''),
(215, 6868, 3, '[]', NULL, 'Prismplate', 'Applies a short duration buff to an ally, causing a portion of their armour to apply to elemental damage taken.', 28, 100, 1, 52494, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(216, 6869, 3, '[]', NULL, 'Brutal Teachings', 'Applies a short duration buff to nearby allies, causing impales they inflict to last for one additional hit.', 28, 100, NULL, 27763, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(217, 10038, 2, '[110,111,112,120,121,122,164,165,166,0,1,23,24,25,154,155,156,142]', NULL, 'Shattering Steel', 'Swing an Axe or Sword, firing projectiles which shatter on impact or soon after being launched, dealing area damage in front of where they shatter.', 12, 100, NULL, 12729, ''),
(218, 11456, 2, '[110,111,112,120,121,122,164,165,166,0,1,23,24,25,154,155,156,142]', NULL, 'Splitting Steel', 'Fire a single projectile that splits on impact or at the targeted location, dealing area damage when it splits and again when the split projectiles explode at the end of their flight.', 1, 100, NULL, 28511, ''),
(219, 10016, 2, '[110,111,112,120,121,122,164,165,166,0,1,23,24,25,154,155,156,142,261]', NULL, 'Lancing Steel', 'Thrust an Axe or Sword forward, consuming Steel Shards to form a cluster of shards. The cluster will fire a number of projectiles in sequence, aiming at enemies in front of or close to it. Steel Shards are gained with the Call of Steel Skill.', 28, 100, NULL, 43812, ''),
(220, 11475, 3, '[]', NULL, 'Call of Steel', 'Calls impale debuffs from enemies, alive or dead, in a large surrounding area to gain steel shards. Deals reflected damage in a smaller area around each enemy based on the impales removed from them. Continues to grant shards over time until reaching maximum or until they are spent.', 1, 100, NULL, 46131, ''),
(221, 329, 0, '[120,121,122,46,164,165,166,83,84,85,26,27,28]', NULL, 'Whirling Blades', 'Dive through enemies, dealing weapon damage. If dual wielding attacks with both weapons, dealing the damage of both in one hit. Only works with Daggers, Claws, and One-Handed Swords.', 10, 100, NULL, 10823, ''),
(222, 10849, 2, '[33,34,35,120,121,122,0,1,154,155,156,126,127,128,103,104,105,26,27,28,157,158]', NULL, 'Venom Gyre', 'Fires a returning projectile that can be caught. Caught projectiles spiral outwards when you use Whirling Blades and do not return.', 12, 100, NULL, 59831, ''),
(223, 1087, 2, '[33,34,35,120,121,122,126,127,128,103,104,105,26,27,28,157,158,49,50,51,62,63,64,191,192,4]', 1088, 'Viper Strike', 'Hits enemies, converting some of the physical damage to chaos damage and inflicting poison which will be affected by modifiers to skill duration. If dual wielding, will strike with both weapons.', 1, 100, NULL, 22227, ''),
(224, 10845, 2, '[33,34,35,120,121,122,126,127,128,103,104,105,26,27,28,157,158,62,63,64,191,192,4]', NULL, 'Pestilent Strike', 'Attacks enemies inflicting a debuff on hit. If a debuffed enemy dies while poisoned, Pestilent Strike inflicts a secondary chaos damage over time debuff on enemies around them, based on the poisons on the slain enemy. ', 28, 100, NULL, 12262, ''),
(225, 10791, 2, '[33,34,35,143,144,145,6,7,157,158,26,27,28,0,1,154,155,156,142,262]', NULL, 'Cobra Lash', 'Fires a poisonous projectile attack that will chain between enemies. ', 1, 100, NULL, 16896, ''),
(226, 3724, 2, '[33,34,35,120,121,122,0,1,154,155,156,126,127,128,103,104,105,26,27,28,157,158]', NULL, 'Profane Strike', 'Attacks with physical and chaos damage. This attack causes balls of unholy energy to launch forth from the enemies hit, divided amongst all enemies hit by the strike. These will deal area attack damage to enemies where they land.', 28, 100, NULL, 36446, ''),
(227, 4882, 0, '[180,181,182,65,66,67,159,232,233,234]', NULL, 'Abyssal Cry', 'Performs a warcry, Hindering nearby enemies and causing them to explode when killed. The Hinder effect is proportional to the number of surrounding enemies. Taunts all nearby enemies to attack the user.', 1, 100, NULL, 14992, ''),
(228, 10045, 1, '[65,66,67,159,232,233,234,37,38,39,148,149,150,174,175,176,157,158,164,165,166]', NULL, 'Seismic Crush', 'Rip stone from the earth, compacting it into a bludgeoning sphere to slam down onto enemies.', 28, 100, 1, 17198, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(229, 1251, 0, '[65,66,67,232,233,234,37,38,39,157,158,148,149,150]', NULL, 'Bloody Warp', 'Teleport to a targeted destination. When the teleport occurs, physical damage is dealt to the area around both the origin and the destination.', 10, 100, NULL, 22724, ''),
(230, 5325, 2, '[37,38,39,232,233,234,148,149,150,174,175,176,49,50,51,157,158,164,165,166]', NULL, 'Blade Vortex', 'This spell creates ethereal blades which orbit in an area around the caster, dealing damage every 0.6 seconds to all enemies in their radius. As more blades are added, the damage becomes greater and more frequent.', 12, 100, NULL, 25718, ''),
(231, 2225, 2, '[37,38,39,148,149,150,174,175,176,49,50,51,157,158,164,165,166,0,1,171,172,173]', 2226, 'Ethereal Knives', 'Fires an arc of knives outwards in front of the caster which deal physical damage.', 1, 100, NULL, 50999, ''),
(232, 9401, 3, '[]', NULL, 'Aspect of the Spider', 'While active, periodically applies a Spider''s Web debuff to nearby Enemies, and Hinders them. Each Spider''s Web on an Enemy increases the Damage they take. Hinder reduces their movement speed.', 34, 100, NULL, 19417, ''),
(233, 11160, 3, '[]', NULL, 'Clutches of the Damned', 'Create a temporary tear through which the grasping hands of damned souls can claw, slowing enemies significantly.', 28, 100, NULL, 26057, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(234, 5305, 2, '[11,12,37,38,39,157,158,148,149,150,174,175,176,232,233,234,10,164,165,166]', NULL, 'Bladefall', 'Ethereal weapons rain from the sky, dealing damage to enemies in a sequence of volleys. Enemies can be hit multiple times where these overlap.', 28, 100, NULL, 37202, ''),
(235, 5306, 2, '[157,158,148,149,150,174,175,176,232,233,234,123,124,125,164,165,166]', NULL, 'Bladefall of Trarthus', 'Casts a buff which causes volleys of ethereal weapons rain from the sky, dealing damage to enemies they impact.', 28, 100, 1, 59477, ''),
(236, 3028, 2, '[11,12,232,233,234,49,50,51,52,53,54,55,56,57,126,127,128,37,38,39,164,165,166,123,124,125,157,158]', 3029, 'Storm Call of Trarthus', 'Sets a marker at a location. After a short duration, a bolt strikes the marker, dealing physical damage around it and causing bolts to strike at any other markers. Bolt impacts will leave behind a pool of boiling blood, which deals physical damage over time to enemies within it for a secondary duration.', 12, 100, NULL, 2187, ''),
(237, 1571, 3, '[]', 1572, 'Tempest Shield', 'Enchants the equipped shield with the power of storms, which lashes out to deal arcing lightning damage to attackers on block.', 16, 100, NULL, 58855, ''),
(238, 1183, 0, '[11,12,37,38,39,232,233,234,58]', NULL, 'Punishment', 'Curses all targets in an area, causing them to be debilitated when they hit enemies and increasing damage they take while on low life.', 24, 100, NULL, 32391, ''),
(239, 3730, 2, '[90,91,92,0,1,6,7,77,78,79,232,233,234,193,194,195,199]', 3731, 'Vaal Molten Strike', 'Attacks with physical and fire damage. This attack causes balls of molten magma to launch forth causing area attack damage to enemies where they land.', 28, 100, 1, 42219, ''),
(240, 3725, 2, '[90,91,92,0,1,6,7,77,78,79,232,233,234,193,194,195,199,263]', NULL, 'Molten Strike', 'Attacks with physical and fire damage. This attack causes balls of molten magma to launch forth from the enemies hit, divided amongst all enemies hit by the strike. These will deal area attack damage to enemies where they land.', 1, 100, NULL, 899, ''),
(241, 9574, 2, '[90,91,92,6,7,77,78,79,232,233,234,120,121,122,191,192,193,194,195,199]', 9575, 'Infernal Blow of Immolation', 'Applies a charged debuff to themselves the first time the mercenary hits an enemy with this skill. Upon reaching 6 charges, or charges expiring, the charged debuff is removed to damage nearby enemies.', 12, 100, NULL, 17147, ''),
(242, 3359, 0, '[49,50,51,65,66,67,159]', NULL, 'Inflame', 'Become enraged and cloaked in flame, gaining a percentage of physical damage as extra fire as well as movement speed and attack speed for a short duration.', 12, 100, NULL, 8295, 'Art/2DArt/SkillIcons/HouseKeitaSkill.dds'),
(243, 1511, 2, '[90,91,92,0,1,6,7,77,78,79,232,233,234,142,171,172,173,6,7,193,194,195,199]', NULL, 'Flamebolt Strike', 'Swings with fiery energies. In addition to converting some physical damage to fire damage, the stored energy is released from the weapon as projectiles as you strike, flying out to hit farther-away enemies. The projectiles cannot miss if the melee attack hit a target.', 12, 100, NULL, 19178, ''),
(244, 4722, 2, '[90,91,92,49,50,51,6,7,71,72,73,232,233,234,83,84,85]', 4723, 'Static Strike', 'Attack with a melee weapon, gaining static energy for a duration if hitting an enemy. While statically charged, frequently hit a number of nearby enemies with beams, dealing attack damage.', 6, 100, NULL, 24931, ''),
(245, 5043, 2, '[90,91,92,0,1,6,7,142,171,172,173,6,7,68,69,70,83,84,85,59,60,61,120,121,122,191,192,86,87,88]', 5044, 'Frost Blades', 'Attacks enemies with increased range, releasing icy blades from the first enemy hit which fly at other enemies.', 1, 100, NULL, 22105, ''),
(246, 5168, 2, '[90,91,92,0,1,6,7,142,68,69,70,83,84,85,59,60,61,0,120,121,122,89,191,192,1,83,84,85,86,87,88]', 5169, 'Wild Strike', 'Strike enemies, converting physical damage to a random element. Depending on the element chosen, causes a fiery explosion, an arcing bolt of lightning, or an icy wave. The same element is not chosen twice in a row.', 28, 100, NULL, 40957, ''),
(247, 12024, 2, '[154,155,156,151,152,153,83,84,85,90,91,92,120,121,122,136,137,138,168,169,170]', NULL, 'Spectral Helix', 'Throws a spectral melee weapon. It spins around while flying in a large spiral, damaging enemies in its path, and bouncing if it collides with walls.', 6, 100, NULL, 37916, ''),
(248, 4029, 3, '[]', NULL, 'Herald of Ice', 'Grants a buff adding cold damage to spells and attacks. If you shatter an enemy, this skill will cause them to explode and deal AoE cold damage to enemies near them. This damage is not affected by modifiers to spell damage.', 16, 100, NULL, 32807, ''),
(249, 11989, 2, '[37,38,39,71,72,73,177,178,179,188,189,190,232,233,234,11,12,93,94,95,148,149,150,86,87,88]', 11990, 'Absolution', 'Damages enemies in an area, applying a debuff for a short duration. If a non-unique enemy dies while affected by the debuff, the corpse will be consumed to summon a Sentinel of Absolution for a secondary duration, or to refresh the duration and life of an existing one instead if you have the maximum number of them. ', 12, 100, NULL, 15611, ''),
(250, 11985, 0, '[180,181,182,232,233,234,65,66,67,159]', NULL, 'Battlemage''s Cry', 'Performs a warcry, taunting nearby enemies to attack the user and exerting subsequent attacks. The user and nearby allies gain a buff that boosts critical strike chance.', 24, 100, NULL, 37344, ''),
(251, 982, 2, '[177,178,179,188,189,190,136,137,138,232,233,234,0,1,120,121,122,37,38,39,148,149,150]', 983, 'Raise Spectre of Transience', 'Raises a spectral version of a defeated foe as a temporary minion.', 28, 100, NULL, 50349, ''),
(252, 3671, 3, '[]', 3672, 'Reinforce: Fallen Bishop', 'Calls on a powerful undead clergyman which curses surrounding enemies.', 28, 100, NULL, 4383, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(253, 3673, 3, '[]', 3674, 'Reinforce: Fallen Emperor', 'Calls on a long dead emperor to deliver brutal justice to deserving enemies.', 28, 100, NULL, 61523, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(254, 3675, 3, '[]', 3676, 'Reinforce: Fallen Osseotitan', 'Calls on a Colossus of cursed bone to inflict pain on your foes.', 28, 100, NULL, 53527, 'Art/2DArt/SkillIcons/HouseAzadiSkill.dds'),
(255, 2262, 2, '[90,91,92,68,69,70,6,7,171,172,173,0,1,232,233,234,59,60,61,22,142]', NULL, 'Ice Shot', 'Fires an arrow that converts some physical damage to cold on its target and converts all physical damage to cold in a cone behind that target.', 1, 100, NULL, 11495, ''),
(256, 12349, 2, '[90,91,92,68,69,70,6,7,171,172,173,0,1,232,233,234,59,60,61,22,142,65,66,67,99,100,101]', NULL, 'Vaal Ice Shot', 'Fires an arrow that converts some physical damage to cold on its target and converts all physical damage to cold in a cone behind that target. Summons a squad of Mirage Sharpshooters for a duration.', 28, 100, 1, 16381, ''),
(257, 1993, 3, '[]', NULL, 'Vaal Grace', 'Casts a temporary aura that grants additional chance to evade attacks, and makes suppressed spell damage unlucky.', 24, 100, 1, 58425, ''),
(258, 8959, 0, '[49,50,51,65,66,67,37,38,39]', NULL, 'Impenetrable Bastion', 'Creates an impenetrable barrier around an allied target, briefly making them completely invulnerable to damage.', 24, 100, 1, 45615, 'Art/2DArt/SkillIcons/HouseKeitaSkill.dds'),
(259, 6183, 2, '[90,91,92,68,69,70,6,7,171,172,173,59,60,61,22,142,65,66,67,99,100,101]', NULL, 'Frigid Forkshot', 'Fires an arrow which forks multiple times as it travels and deals high cold damage to those hit.', 5, 100, 1, 18232, 'Art/2DArt/SkillIcons/HouseBardiyaSkill.dds'),
(260, 5271, 2, '[90,91,92,68,69,70,0,1,232,233,234,59,60,61,22,142,65,66,67,99,100,101]', NULL, 'Icicle Rain', 'Fires arrows up in the air, to rain down in an area. Each arrow deals cold area damage around where it lands, and they will all overlap on the targeted location.', 28, 100, NULL, 24409, 'Art/2DArt/SkillIcons/HouseBardiyaSkill.dds'),
(261, 10618, 3, '[]', NULL, 'Dash', 'Performs a series of quick teleports towards a targeted location.', 4, 100, NULL, 60723, ''),
(262, 3160, 2, '[120,121,122,0,1,217,218,219,142,151,152,153,154,155,156,164,165,166,6,7,171,172,173]', NULL, 'Barrage of Volley Fire', 'Fires projectiles repeatedly with a Bow or Wand. These projectiles have a small randomised spread.', 12, 100, NULL, 12260, ''),
(263, 1956, 3, '[]', NULL, 'Haste', 'Casts an aura that increases the movement speed, attack speed and cast speed.', 24, 100, NULL, 52155, ''),
(264, 4623, 2, '[65,66,67,49,50,51,120,121,122,154,155,156,177,178,179,188,189,190,83,84,85,159,0,1,171,172,173,6,7]', NULL, 'Mirror Arrow', 'Fires an arrow at the target destination. When the arrow lands, a clone is summoned.', 10, 100, NULL, 65447, ''),
(265, 4616, 1, '[65,66,67,49,50,51,120,121,122,154,155,156,177,178,179,188,189,190]', NULL, 'Blink Arrow', 'Fires an arrow at the target destination. When the arrow lands, the user is teleported to it and a clone is summoned at the old location. The clone is a minion that copies the bow and quiver.', 10, 100, NULL, 10722, ''),
(266, 367, 1, '[120,121,122,0,1,171,172,173,6,7,74,22]', NULL, 'Frenzy', 'Performs an attack with a ranged weapon that grants a frenzy charge if it hits.', 16, 100, NULL, 58592, ''),
(267, 11074, 2, '[232,233,234,90,91,92,120,121,122,229,230,231,227,148,149,150,174,175,176,225]', NULL, 'Holy Hammers', 'Slams the ground, calling down a Holy Hammer from above. On hitting an enemy, another Hammer will cascade forward, repeating if further enemies are hit, up to a cap. A Power Charge can be expended to call down additional Hammers to either side of the initial slam.', 1, 100, NULL, 28506, ''),
(268, 11078, 2, '[120,121,122,232,233,234,177,178,179,191,192,4,238,265]', NULL, 'Holy Strike', 'Infuse your weapon with holy energy and swing. Successfully hitting an enemy will summon forth a copy of your Main Hand weapon as a Holy Armament. These Holy Armaments are undamageable minions, and will attack the enemies you target with Holy Strike.', 1, 100, NULL, 38655, ''),
(269, 11062, 2, '[232,233,234,120,121,122,90,91,92,126,127,128,49,50,51,55,56,57,199,264]', 11063, 'Conflagration', 'Fire arrows into the air that rain down around the targeted area, dealing area damage on impact and leaving the arrows stuck in the ground for a duration. If you move close to a stuck arrow, it will explode, dealing area damage and applying a fire damage over time debuff, as well as causing other stuck arrows in range to also explode.', 28, 100, NULL, 21962, ''),
(270, 11067, 2, '[120,121,122,0,1,19,90,91,92,83,84,85,86,87,88,148,149,150,174,175,176,232,233,234]', NULL, 'Kinetic Rain of Impact', 'Swing your wand to cause a number of projectiles to rain down within a large area in front of you, directly targeting the locations of enemies in the area. The locations where each projectile will land are shown with markers before they fall. Each projectile explodes when hitting the ground, dealing area damage.', 28, 100, NULL, 32089, ''),
(271, 290, 2, '[120,121,122,90,91,92,83,84,85,148,149,150,174,175,176,232,233,234,191,192,4,68,69,70]', 291, 'Elemental Hit of Ice', 'If this attack hits an enemy, it will deal damage in an area around them, with the radius being larger if that enemy is suffering from a cold ailment.', 68, 100, NULL, 8708, '');
